/*
 * A122556  Primes occur infinitely often, with first appearance in order.
 *          Between each occurrence of a prime p, there are p distinct primes.
 * https://oeis.org/A122556
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) is generated by the rule that every prime p appears
 *            infinitely often, and between two consecutive appearances of p
 *            there are exactly p distinct primes. The algorithm keeps, for
 *            each prime, a counter of how many distinct primes have appeared
 *            since its last occurrence; when that counter reache...
 * Range:     u8 n <= 93, u16 n <= 93, u32 n <= 93, u64 n <= 93, u128 n <= 93,
 *            big any n
 * Helpers:   build_primes
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include "../utils/build_primes.h"   /* provides build_primes */

#define PRIME_LIMIT 200000         /* enough for n up to ~10 000 */

static uint64_t *prime_vals = NULL;   /* array of prime values */
static size_t prime_count = 0;        /* number of primes generated */

/* per‑prime state */
static bool *seen = NULL;            /* seen[prime_index] */
static seq_t *cnt = NULL;           /* cnt[prime_index]  */
static uint64_t **bitset = NULL;     /* bitset[prime_index][word] */

/* dynamic list of primes that have appeared */
static idx_t *seen_idx = NULL;
static size_t seen_size = 0;
static size_t seen_cap = 0;

/* cache of produced sequence values */
static seq_t *cache = NULL;
static size_t cache_size = 0;
static size_t cache_cap = 0;

static size_t bitset_words = 0;      /* number of 64‑bit words per row */
static idx_t next_unused_prime = 0;  /* index of the first unseen prime */

/* --------------------------------------------------------------------- */
static void _init(void)
{
    if (prime_vals != NULL) return;  /* already initialized */

    /* Generate primes up to PRIME_LIMIT */
    idx_t *tmp = NULL;
    size_t nprimes = 0;
    build_primes((idx_t)PRIME_LIMIT, &tmp, &nprimes);
    prime_vals = (uint64_t*)malloc(nprimes * sizeof(uint64_t));
    for (size_t i = 0; i < nprimes; ++i)
        prime_vals[i] = (uint64_t)tmp[i];
    prime_count = nprimes;
    free(tmp);                       /* build_primes allocated with malloc */

    /* per‑prime arrays */
    seen  = (bool*)calloc(prime_count, sizeof(bool));
    cnt   = (seq_t*)calloc(prime_count, sizeof(seq_t));

    /* bitset: one row per prime */
    bitset_words = (prime_count + 63u) >> 6;
    bitset = (uint64_t**)calloc(prime_count, sizeof(uint64_t*));
    for (size_t i = 0; i < prime_count; ++i)
        bitset[i] = (uint64_t*)calloc(bitset_words, sizeof(uint64_t));

    /* seen indices array */
    seen_cap  = 64;
    seen_idx  = (idx_t*)calloc(seen_cap, sizeof(idx_t));

    /* cache */
    cache_cap  = 0;
    cache_size = 0;
    cache      = NULL;
}

/* --------------------------------------------------------------------- */
static void _ensure_cache(size_t needed)
{
    if (cache_cap >= needed) return;
    size_t new_cap = cache_cap ? cache_cap << 1 : 64;
    while (new_cap < needed) new_cap <<= 1;
    cache = (seq_t*)realloc(cache, new_cap * sizeof(seq_t));
    cache_cap = new_cap;
}

/* --------------------------------------------------------------------- */
static void _generate_up_to(idx_t n)
{
    if (n == 0) return;
    if (cache_size >= n) return;
    _init();

    while (cache_size < n) {
        /* 1. Find a prime whose counter has reached its limit */
        idx_t q_idx = (idx_t)-1;
        for (size_t k = 0; k < seen_size; ++k) {
            size_t i = seen_idx[k];
            if (cnt[i] == (seq_t)prime_vals[i]) {  /* ready to appear again */
                q_idx = (idx_t)i;
                break;   /* smallest eligible prime due to ascending order */
            }
        }

        /* 2. If none, take the first unseen prime */
        if (q_idx == (idx_t)-1) {
            while (next_unused_prime < prime_count && seen[next_unused_prime])
                ++next_unused_prime;
            q_idx = next_unused_prime;
            seen[q_idx] = true;

            /* store in seen indices list */
            if (seen_size == seen_cap) {
                seen_cap <<= 1;
                seen_idx = (idx_t*)realloc(seen_idx, seen_cap * sizeof(idx_t));
            }
            seen_idx[seen_size++] = q_idx;
            ++next_unused_prime;
        }

        /* 3. Output prime value */
        seq_t val = (seq_t)prime_vals[q_idx];
        _ensure_cache(cache_size + 1);
        cache[cache_size++] = val;

        /* 4. Update all other seen primes with this new prime */
        for (size_t t = 0; t < seen_size; ++t) {
            size_t i = seen_idx[t];
            if (i == (size_t)q_idx) continue;
            uint64_t *row = bitset[i];
            size_t word = q_idx >> 6;
            uint64_t mask = 1ULL << (q_idx & 63u);
            if (!(row[word] & mask)) {
                row[word] |= mask;
                ++cnt[i];
            }
        }

        /* 5. Reset q's own state for next segment */
        memset(bitset[q_idx], 0, bitset_words * sizeof(uint64_t));
        cnt[q_idx] = 0;
    }
}

/* --------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n == 0) return 0;
    _generate_up_to(n);
    return cache[n - 1];
}
